<script setup>
import {computed,onBeforeUnmount,reactive,ref,watch} from 'vue';
import {ElMessage} from 'element-plus';
import {apiClient,currentApiCacheScope} from '../../utils/api.js';
const props=defineProps({modelValue:Boolean,productId:Number,inboundId:Number,remove:Boolean}),emit=defineEmits(['update:modelValue','saved']);
const visible=computed({get:()=>props.modelValue,set:v=>emit('update:modelValue',v)}),loading=ref(false),saving=ref(false),error=ref(''),data=ref(null),preview=ref(null),submitted=ref(null);
const form=reactive({quantity:1,amount:0,shipping_amount:0,courier_company:'',tracking_number:'',reason:''});
const batch=computed(()=>data.value?.batches?.find(r=>Number(r.id)===props.inboundId));
let version=0,disposed=false;
async function load(){const token=++version,scope=currentApiCacheScope();loading.value=true;error.value='';preview.value=null;submitted.value=null;try{const r=await apiClient.get(`/api/procurement/ledger?product_id=${props.productId}&include_fbp=0`,{noCache:true});if(disposed||token!==version||scope!==currentApiCacheScope())return;data.value=r;const row=batch.value;if(!row||row.status!=='pending_arrival'||row.received_at)throw Error('此批次已到货或关闭，请刷新列表');Object.assign(form,{quantity:props.remove?0:Number(row.quantity),amount:props.remove?0:Number(row.amount),shipping_amount:props.remove?0:Number(row.shipping_amount||0),courier_company:row.courier_company||'',tracking_number:row.tracking_number||'',reason:''});}catch(e){if(!disposed&&token===version&&scope===currentApiCacheScope())error.value=e.message;}finally{if(token===version)loading.value=false;}}
async function next(){if(!form.reason.trim())return ElMessage.warning('请填写修改或删除原因');const scope=currentApiCacheScope(),token=version;saving.value=true;error.value='';try{const body={...form,product_id:props.productId,inbound_id:props.inboundId,action_type:'revise_pending_batch',revision:data.value.revision,request_key:crypto.randomUUID()};const r=await apiClient.post('/api/procurement/ledger/preview',body);if(disposed||token!==version||scope!==currentApiCacheScope())return;submitted.value={...body,revision:r.revision};preview.value=r;}catch(e){if(!disposed&&token===version&&scope===currentApiCacheScope())error.value=e.message;}finally{if(token===version)saving.value=false;}}
async function save(){if(!submitted.value)return;const scope=currentApiCacheScope(),token=version;saving.value=true;error.value='';try{await apiClient.post('/api/procurement/ledger',submitted.value);if(disposed||token!==version||scope!==currentApiCacheScope())return;ElMessage.success(props.remove?'记录已作废，采购金额与在途覆盖已更新':'批次与采购记录已更新');visible.value=false;emit('saved');}catch(e){if(!disposed&&token===version&&scope===currentApiCacheScope())error.value=e.message;}finally{if(token===version)saving.value=false;}}
watch(()=>[props.modelValue,props.productId,props.inboundId,props.remove],()=>{if(props.modelValue)load();},{immediate:true});
function scopeChanged(){++version;visible.value=false;}window.addEventListener('erp:auth-scope-changed',scopeChanged);
onBeforeUnmount(()=>{disposed=true;++version;window.removeEventListener('erp:auth-scope-changed',scopeChanged);});
</script>
<template>
 <el-dialog v-model="visible" :title="remove?'删除待到货记录':'编辑采购待到货批次'" width="min(620px,94vw)" append-to-body :close-on-click-modal="false" :close-on-press-escape="!saving" :show-close="!saving">
  <div v-loading="loading"><el-alert v-if="error" :title="error" type="error" :closable="false"/><p>{{data?.product?.name}} · 批次 #{{inboundId}}</p>
   <template v-if="preview"><el-alert type="warning" :closable="false" :title="remove?'将作废此条误录批次，保留审计记录':'确认修改当前待到货批次'"/><p>待到货数量：{{batch.quantity}} → {{submitted.quantity}} 件</p><p>货款：¥{{batch.amount}} → ¥{{submitted.amount}}；运费：¥{{batch.shipping_amount||0}} → ¥{{submitted.shipping_amount}}</p><p>本地实物不变；采购金额、在途覆盖和需求建议同步更新。</p><p v-if="preview.affected_orders?.length">关联 {{preview.affected_orders.length}} 条订单的采购覆盖将减少，请关注新的缺口。</p><p>原因：{{submitted.reason}}</p></template>
   <el-form v-else-if="batch&&!loading" label-position="top" :disabled="saving"><el-alert v-if="remove" type="warning" :closable="false" title="仅用于重复或误录作废。实际退货退款请使用采购对账，不以删除记录代替退款。"/><template v-else><el-form-item label="待到货数量"><el-input-number v-model="form.quantity" :min="1" :max="1000000" :precision="0"/></el-form-item><el-form-item label="本批次货款（人民币）"><el-input-number v-model="form.amount" :min="0" :precision="2"/></el-form-item><el-form-item label="本批次运费（人民币）"><el-input-number v-model="form.shipping_amount" :min="0" :precision="2"/></el-form-item><el-form-item label="快递公司"><el-input v-model="form.courier_company" maxlength="128"/></el-form-item><el-form-item label="快递单号"><el-input v-model="form.tracking_number" maxlength="128"/></el-form-item></template><el-form-item :label="remove?'删除原因':'修改原因'" required><el-input v-model="form.reason" type="textarea" maxlength="500" show-word-limit/></el-form-item></el-form>
  </div>
  <template #footer><el-button :disabled="saving" @click="visible=false">取消</el-button><el-button v-if="preview" :disabled="saving" @click="preview=null;submitted=null">返回修改</el-button><el-button :type="remove?'danger':'primary'" :loading="saving" :disabled="loading||!batch" @click="preview?save():next()">{{preview?(remove?'确认删除':'确认保存'):'下一步确认'}}</el-button></template>
 </el-dialog>
</template>
